   161			organizationId: req.organizationId,
   162			principalKind: req.principalKind,
   163			principalId: req.principalId ?? null,
   164			ownerAgentId,
   165			ownerResolved,
   166			action: req.action,
   167			entityTypeSlug: req.entityTypeSlug,
   168			entityId: req.action === "delete" ? req.entityId : undefined,
