  1015			throw new ToolUserError(
  1016				`Un-merge failed: ${err instanceof Error ? err.message : String(err)}`,
  1017				409,
  1018			);
  1019		}
  1020	
  1021		return {
  1022			action: "unmerge",
  1023			success: true,
