 154	/** Verify the resource exists and the caller has access. Returns the numeric row id. */
 155	async function verifyAccess(
 156	  sql: ReturnType<typeof getDb>,
 157	  args: ManageViewTemplatesArgs,
 158	  ctx: ToolContext,
 159	  requireWrite: boolean
 160	): Promise<number> {
 161	  if (requireWrite && !ctx.userId) throw new Error('Authentication required');
 162	
 163	  const rt = args.resource_type;
 164	
 165	  // Boundary validation (`withValidatedArgs`) guarantees resource_type and
 166	  // resource_id are present and well-typed, but a whitespace-only string
 167	  // still satisfies the schema and would query for a blank slug.
 168	  if (String(args.resource_id).trim() === '') {
 169	    throw new ToolUserError(`resource_id is required (got ${JSON.stringify(args.resource_id)})`);
 170	  }
 171	
 172	  const id = rid(args);
 173	
 174	  if (rt === 'entity_type') {
 175	    const rows = await sql`
 176	      SELECT id, organization_id, created_by FROM entity_types
 177	      WHERE slug = ${id} AND deleted_at IS NULL
 178	        AND (organization_id = ${ctx.organizationId} OR organization_id IS NULL)
 179	      LIMIT 1
 180	    `;
 181	    if (rows.length === 0) throw new ToolUserError(`Entity type '${id}' not found`, 404);
 182	    if (requireWrite && rows[0].organization_id !== ctx.organizationId) {
 183	      throw new ToolUserError(`Access denied: entity type '${id}' belongs to another organization`, 403);
 184	    }
 185	    return Number(rows[0].id);
 186	  }
 187	
 188	  // entity
 189	  const numericId = Number(id);
 190	  if (!Number.isFinite(numericId)) {
 191	    throw new ToolUserError(
 192	      `resource_id must be a numeric entity id for resource_type 'entity' (got ${JSON.stringify(args.resource_id)})`
 193	    );
 194	  }
 195	  const rows = await sql`
 196	    SELECT id FROM entities
 197	    WHERE id = ${numericId}
 198	      AND organization_id = ${ctx.organizationId}
 199	      AND deleted_at IS NULL
 200	    LIMIT 1
 201	  `;
 202	  if (rows.length === 0) throw new Error(`Entity ${id} not found`);
 203	  return Number(rows[0].id);
 204	}
