 210	function validateDataSources(dataSources: unknown): void {
 211	  if (dataSources === undefined || dataSources === null) return;
 212	  if (typeof dataSources !== 'object' || Array.isArray(dataSources)) {
 213	    throw new Error('data_sources must be an object');
 214	  }
 215	  for (const [name, entry] of Object.entries(dataSources as Record<string, unknown>)) {
 216	    if (!entry || typeof entry !== 'object' || Array.isArray(entry)) {
 217	      throw new Error(`data_sources.${name}: must be an object with a query`);
 218	    }
 219	    const e = entry as Record<string, unknown>;
 220	    if (typeof e.query !== 'string' || !e.query.trim()) {
 221	      throw new Error(`data_sources.${name}: query must be a non-empty string`);
 222	    }
 223	    // Save-time: also validates SQL syntax and schema-qualified refs
 224	    validateDataSourceQuery(name, e.query.trim(), true);
 225	  }
 226	}
