1074	/** Reserved $-prefixed proposal keys that map to entity ATTRIBUTES, not metadata. */
1075	const ATTRIBUTE_FIELD_KEYS = new Set(["$name", "$parent_id", "$content"]);
1076	
1077	/**
1078	 * Apply an approved field-change proposal. The approver endorsed the value, so
1079	 * metadata fields are written AND marked human-owned via
1080	 * mergeEntityFields(source='human'). Reserved $-attribute keys ($name,
1081	 * $parent_id, $content) write the entity attribute directly — with the same
1082	 * staleness guard: an attribute a human changed after the proposal was queued
1083	 * is left alone.
1084	 */
1085	export async function applyEntityFieldChangeProposal(
1086		proposal: EntityFieldChangeProposal,
1087		approverUserId: string | null,
1088	): Promise<FieldMergeResult> {
1089		const sql = getDb();
1090		const metadataFields = Object.fromEntries(
1091			Object.entries(proposal.fields).filter(
1092				([key]) => !ATTRIBUTE_FIELD_KEYS.has(key),
1093			),
1094		);
1095		const attributeFields = Object.fromEntries(
1096			Object.entries(proposal.fields).filter(([key]) =>
1097				ATTRIBUTE_FIELD_KEYS.has(key),
1098			),
1099		);
1100		return await sql.begin(async (tx) => {
1101			const merge =
1102				Object.keys(metadataFields).length > 0
1103					? await mergeEntityFields({
1104							tx,
1105							entityId: proposal.entity_id,
1106							fields: metadataFields,
1107							source: "human",
1108							actorId: approverUserId,
1109							note: proposal.reason ?? null,
1110							// Don't overwrite a field the human re-edited after this proposal was queued.
1111							expectedCurrent: proposal.current ?? null,
1112						})
1113					: ({
1114							changed: false,
1115							applied: {},
1116							blocked: {},
1117							stale: {},
1118							affirmed: [],
1119							nextMetadata: {},
1120							nextControls: {},
1121						} satisfies FieldMergeResult);
1122			if (Object.keys(attributeFields).length > 0) {
1123				const rows = await tx<{
1124					name: string | null;
1125					parent_id: number | null;
1126					content: string | null;
1127				}>`
1128	        SELECT name, parent_id, content FROM entities
1129	        WHERE id = ${proposal.entity_id} AND deleted_at IS NULL
1130	        FOR UPDATE
1131	      `;
1132				if (rows.length === 0) {
1133					throw new ToolUserError(`Entity ${proposal.entity_id} not found`, 404);
1134				}
1135				const live = {
1136					$name: rows[0].name ?? null,
1137					$parent_id:
1138						rows[0].parent_id == null ? null : Number(rows[0].parent_id),
1139					$content: rows[0].content ?? null,
1140				} as Record<string, unknown>;
1141				const apply: Record<string, unknown> = {};
1142				for (const [key, proposed] of Object.entries(attributeFields)) {
1143					const expected = proposal.current?.[key];
1144					if (
1145						proposal.current &&
1146						Object.hasOwn(proposal.current, key) &&
1147						JSON.stringify(live[key] ?? null) !== JSON.stringify(expected ?? null)
1148					) {
1149						merge.stale[key] = {
1150							expected: expected ?? null,
1151							live: live[key] ?? null,
1152						};
1153						continue;
1154					}
1155					apply[key] = proposed;
1156					merge.applied[key] = { old: live[key] ?? null, new: proposed };
1157				}
1158				if (Object.keys(apply).length > 0) {
1159					const nextName =
1160						"$name" in apply ? String(apply.$name ?? "") || null : null;
1161					await patchEntityRows({
1162						tx,
1163						ids: [proposal.entity_id],
1164						patch: {
1165							...(nextName !== null ? { name: nextName } : {}),
1166							...("$parent_id" in apply
1167								? { parentId: apply.$parent_id as number | null }
1168								: {}),
1169							...("$content" in apply
1170								? { content: apply.$content as string | null }
1171								: {}),
1172						},
1173					});
1174				}
1175			}
1176			return merge;
1177		});
1178	}
