 443	/**
 444	 * The single human owner across a proposal's gated field paths, from
 445	 * `entities.field_controls[field].set_by` (stamped on every human edit).
 446	 * Exactly one distinct owner → that user; mixed owners or none → null
 447	 * (admin-only routing/authority). Reserved $-attributes ($name/$parent_id/
 448	 * $content) have no field_controls entry, so they contribute no owner.
 449	 */
 450	async function resolveProposalFieldOwner(
 451		organizationId: string,
 452		entityId: number,
 453		fieldPaths: string[],
 454	): Promise<string | null> {
 455		const rows = await getDb()<{ field_controls: unknown }>`
 456	    SELECT field_controls FROM entities
 457	    WHERE id = ${entityId}
 458	      AND organization_id = ${organizationId}
 459	      AND deleted_at IS NULL
 460	    LIMIT 1
 461	  `;
 462		if (rows.length === 0) return null;
 463		const controls = (
 464			typeof rows[0].field_controls === "string"
 465				? JSON.parse(rows[0].field_controls)
 466				: (rows[0].field_controls ?? {})
 467		) as Record<string, { set_by?: string | null }>;
 468		const owners = new Set<string>();
 469		for (const path of fieldPaths) {
 470			const setBy = controls[path]?.set_by;
 471			if (setBy) owners.add(setBy);
 472		}
 473		return owners.size === 1 ? [...owners][0] : null;
 474	}
