455		name: string;
456		baseSlug: string;
457		sourceRunId: number;
458		caseKey: string;
459		metadata: Record<string, unknown>;
460	}): Promise<{ entityId: number; created: boolean } | null> {
461		const { sql } = params;
462		for (let attempt = 1; attempt <= SLUG_DISAMBIGUATION_ATTEMPTS; attempt++) {
463			const slug =
464				attempt === 1 ? params.baseSlug : `${params.baseSlug}-${attempt}`;
465			const inserted = await tryInsertEntityRow({
466				tx: sql,
467				row: {
