472					metadata: params.metadata,
473					createdBy: params.createdBy,
474				},
475			});
476			if (inserted) {
477				return { entityId: Number(inserted.id), created: true };
478			}
479	
480			// Soft-deleted rows still hold the slug (the index is not partial), so look
481			// without the `deleted_at` filter and only adopt a LIVE matching case.
482			const owner = (await sql`
483	      SELECT e.id, e.metadata, e.deleted_at, et.slug AS type_slug
484	      FROM entities e
